import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "volume-2",
  "category": "Media",
  "viewBox": "0 0 24 24",
  "mode": "stroke",
  "strokeWidth": 2,
  "motion": "bounce",
  "parts": [
    {
      "tag": "path",
      "attrs": {
        "d": "M15 8a5 5 0 0 1 0 8"
